#[path = "../hopcue/rim.rs"]
mod rim;
#[path = "../restpit/soak.rs"]
mod soak;
#[path = "../shardfold/read.rs"]
mod read;

use std::fs;

pub fn fold() -> Result<(Vec<(i32, String)>, i32), i32> {
    let wall = fs::read_to_string("/app/opstext/WALL")
        .map_err(|_| 1)?
        .trim()
        .parse::<i32>()
        .map_err(|_| 1)?;
    let picked = rim::rim(wall, read::list("/app/daywell")?);
    if picked.is_empty() {
        let _ = fs::remove_dir_all("/app/packbay/stage");
        let _ = fs::remove_dir_all("/app/packbay/latest");
        fs::create_dir_all("/app/packbay/stage").map_err(|_| 1)?;
        fs::create_dir_all("/app/packbay/latest").map_err(|_| 1)?;
        return Err(1);
    }

    let mut taken = 0i32;
    for (_, source) in &picked {
        taken = taken.checked_add(read::nlines(source)?).ok_or(1)?;
    }

    soak::soak(&picked, "/app/packbay/stage")?;
    soak::soak(&picked, "/app/packbay/latest")?;
    fs::create_dir_all("/app/bloturn").map_err(|_| 1)?;
    fs::write(
        "/app/bloturn/ledger.json",
        format!("{{\"taken\":{}}}", taken),
    )
    .map_err(|_| 1)?;
    Ok((picked, taken))
}
EOF
cat > /app/millrib/gait.rs <<'EOF'
use std::fs;

fn emit(probe: &str, matched: i32, taken: i32) -> Result<(), i32> {
    let tpl = fs::read_to_string("/app/millrib/sheet.tpl").map_err(|_| 1)?;
    let out = tpl
        .replace("__P__", probe)
        .replace("__M__", &matched.to_string())
        .replace("__T__", &taken.to_string());
    fs::create_dir_all("/app/bloturn").map_err(|_| 1)?;
    fs::write("/app/bloturn/check.json", out).map_err(|_| 1)
}

pub fn gait(taken: i32, files: &[(i32, String)]) -> i32 {
    let _ = fs::remove_file("/app/bloturn/GUARD");
    if files.is_empty() {
        return 1;
    }

    // This is deliberately independent of ledger.json and the staged copies:
    // every selected source is reopened from /app/daywell for the live check.
    let mut matched = 0i32;
    for (_, path) in files {
        let text = match fs::read_to_string(path) {
            Ok(text) => text,
            Err(_) => return 1,
        };
        let count = text.lines().filter(|line| !line.trim().is_empty()).count() as i32;
        matched = match matched.checked_add(count) {
            Some(total) => total,
            None => return 1,
        };
    }
    if matched != taken {
        return 1;
    }
    let probe = match files.last() {
        Some((_, path)) => path.as_str(),
        None => return 1,
    };
    if emit(probe, matched, taken).is_err() {
        return 1;
    }
    if fs::write("/app/bloturn/GUARD", "ok").is_err() {
        return 1;
    }
    0
}
EOF

